import{X as e,Y as t,ct as n,t as r}from"./chunks/framework.CaFWb3SA.js";var i=JSON.parse(`{"title":"使用指南","description":"","frontmatter":{},"headers":[],"relativePath":"translation/Usage.md","filePath":"translation/Usage.md"}`),a={name:`translation/Usage.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="使用指南" tabindex="-1">使用指南 <a class="header-anchor" href="#使用指南" aria-label="Permalink to “使用指南”">​</a></h1><blockquote><p>翻译自原文档：<a href="https://osdn.net/projects/emuera/wiki/howto" target="_blank" rel="noreferrer">https://osdn.net/projects/emuera/wiki/howto</a></p></blockquote><h2 id="运行环境" tabindex="-1">运行环境 <a class="header-anchor" href="#运行环境" aria-label="Permalink to “运行环境”">​</a></h2><p>需要 .NET Framework 2.0 环境。</p><p>（注：当前版本的 Emuera 已可运行在更高版本的 .NET Framework 上。）</p><p>如果出现<code>应用程序无法正常启动</code>之类错误而无法启动，说明没有安装 .NET Framework 2.0。请从微软官网下载并安装 .NET Framework 2.0 运行时。</p><h2 id="使用方法" tabindex="-1">使用方法 <a class="header-anchor" href="#使用方法" aria-label="Permalink to “使用方法”">​</a></h2><p>把 <code>EmueraXXX.exe</code> 放在与 <code>eramaker.exe</code> 相同的文件夹中并启动。</p><p>（<code>XXX</code> 是表示版本的编号。另外，根据环境设置，<code>.exe</code> 可能不显示。）</p><p>如果无法启动，请阅读上面的<code>运行环境</code>一节。</p><p>启动后会立即生成 <code>emuera.config</code>，出错时会生成 <code>emuera.log</code>。</p><p>基本操作与 <code>eramaker.exe</code> 几乎相同，但可以用鼠标操作。</p><p>用鼠标对准选项（被 <code>[]</code> 包围的数字）并点击即可。</p><ul><li>用 <code>Esc</code> 键或右键可以跳到下一个选项；如果持续按住右键再选择选项，则选择后立刻跳到下一个选项；</li><li>可以用 <code>Ctrl+V</code> 粘贴剪贴板内容；</li><li>与 <code>eramaker.exe</code> 一样，按上下方向键可以调出之前的输入。</li></ul><p>用 EraMakerEx 转换过的文件也可以直接运行。不过该功能默认关闭，需要时请在<code>帮助</code>→<code>设置</code>中勾选<code>使用 _Rename.csv</code>。</p><h2 id="宏" tabindex="-1">宏 <a class="header-anchor" href="#宏" aria-label="Permalink to “宏”">​</a></h2><p>Emuera 带有简单的宏功能。</p><p>例如输入 <code>\\e</code>，就相当于按 <code>Esc</code> 键或右键，跳到下一个选项。</p><p>输入 <code>\\n</code> 会分隔输入，进入下一次输入。例如输入 <code>0\\e\\n1\\e\\n</code>，就会输入 <code>0</code> 并跳到下一个选项，再输入 <code>1</code> 并跳到下一个选项。</p><p>此外，<code>(～～)*n</code> 会把括号内的输入重复 n 次。<code>(0\\e\\n)*3</code> 等同于 <code>0\\e\\n0\\e\\n0\\e\\n</code>。</p><p>宏执行过程中按 <code>Esc</code> 键可以中断。</p><h3 id="把宏保存到功能键" tabindex="-1">把宏保存到功能键 <a class="header-anchor" href="#把宏保存到功能键" aria-label="Permalink to “把宏保存到功能键”">​</a></h3><p>创建的宏可以保存到 <code>F1</code>～<code>F12</code> 键上。</p><ul><li>按住 <code>Shift</code> 再按 <code>F1</code>～<code>F12</code>，即可把当前输入内容保存到对应的功能键；</li><li>之后按 <code>F1</code>～<code>F12</code> 就能输入保存的宏；</li><li>保存的宏会存放到 <code>macro.txt</code>。</li></ul><p>（需要启用配置项<code>使用键盘宏</code>。）</p><p>此外，按住 <code>Ctrl</code> 再按数字键 <code>0</code>～<code>9</code> 可以切换宏分组。（启动 Emuera 时默认选择分组 0。）</p><p>分组 0 的 <code>F1</code>～<code>F12</code> 与分组 1 的 <code>F1</code>～<code>F12</code> 可以保存不同的宏，因此能保存更多宏。也可以在输入框上右键弹出的上下文菜单中切换分组。</p><h3 id="直接编辑-macro-txt" tabindex="-1">直接编辑 macro.txt <a class="header-anchor" href="#直接编辑-macro-txt" aria-label="Permalink to “直接编辑 macro.txt”">​</a></h3><p>也可以用文本编辑器直接编辑 <code>macro.txt</code>：</p><ul><li>在<code>マクロキーF○:</code>（宏键 F○）的冒号右侧，写入按下 <code>F○</code> 时要输入的宏；</li><li><code>G×:マクロキーF○:</code> 是选择分组 X 的宏；</li><li>修改<code>グループ×:マクログループ×に設定</code>（分组 ×：设为宏分组 ×）右侧的消息，可以改变切换到分组 X 时显示的文本。</li></ul><h2 id="菜单" tabindex="-1">菜单 <a class="header-anchor" href="#菜单" aria-label="Permalink to “菜单”">​</a></h2><p>要使用菜单，配置中的<code>使用菜单</code>必须启用。默认启用。</p><h3 id="文件" tabindex="-1">文件 <a class="header-anchor" href="#文件" aria-label="Permalink to “文件”">​</a></h3><h4 id="重启" tabindex="-1">重启 <a class="header-anchor" href="#重启" aria-label="Permalink to “重启”">​</a></h4><p>重新启动 Emuera。</p><p>请注意，如果不保存，正在运行的游戏信息会丢失。</p><h4 id="保存日志" tabindex="-1">保存日志 <a class="header-anchor" href="#保存日志" aria-label="Permalink to “保存日志”">​</a></h4><p>把过去的日志保存到文件中。保存的最大行数与历史日志的行数相同。</p><h4 id="返回标题画面" tabindex="-1">返回标题画面 <a class="header-anchor" href="#返回标题画面" aria-label="Permalink to “返回标题画面”">​</a></h4><p>回到标题画面。</p><p>请注意，如果不保存，正在运行的游戏信息会丢失。</p><h4 id="重新加载代码" tabindex="-1">重新加载代码 <a class="header-anchor" href="#重新加载代码" aria-label="Permalink to “重新加载代码”">​</a></h4><p>在保留游戏信息的情况下重新读取 <code>.erb</code> 文件。</p><p>对于已经被调用过的函数，会执行之前的代码。旧代码会一直保留在内存中，直到被调用的函数结束，因此连续使用可能导致内存不足。</p><h4 id="退出" tabindex="-1">退出 <a class="header-anchor" href="#退出" aria-label="Permalink to “退出”">​</a></h4><p>退出 Emuera。</p><h3 id="帮助" tabindex="-1">帮助 <a class="header-anchor" href="#帮助" aria-label="Permalink to “帮助”">​</a></h3><h4 id="设置" tabindex="-1">设置 <a class="header-anchor" href="#设置" aria-label="Permalink to “设置”">​</a></h4><p>修改各项设置。配置的详细说明请参阅<a href="./Config_Settings.html">配置项详解</a>。</p>`,49)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};